def choose_strategy(can_rollback, rollback_data_loss, fix_time_minutes, severity):
    if not can_rollback:
        return "Forward fix (rollback impossible)"
    if rollback_data_loss and severity == "SEV-1":
        return "Forward fix (data loss prevents rollback)"
    if fix_time_minutes <= 30:
        return "Forward fix (fast enough)"
    return "Rollback (safest and fastest)"

# Examples
print(choose_strategy(True, False, 15, "SEV-1"))  # Rollback
print(choose_strategy(True, True, 15, "SEV-1"))   # Forward fix
